import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Team } from '@/types/api';

import { getTeamsQueryOptions } from './get-teams';

export const updateTeamInputSchema = z.object({
  name: z.string().trim().min(1, 'Required'),
});

export type UpdateTeamInput = z.infer<typeof updateTeamInputSchema>;

export const updateTeam = ({
  teamId,
  data,
}: {
  teamId: string;
  data: UpdateTeamInput;
}): Promise<Team> => {
  return api.patch(`/teams/${teamId}`, data);
};

type UseUpdateTeamOptions = {
  mutationConfig?: MutationConfig<typeof updateTeam>;
};

export const useUpdateTeam = ({ mutationConfig }: UseUpdateTeamOptions = {}) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getTeamsQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateTeam,
  });
};
EOF
